{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "Assign"
  ],
  "properties": {
    "Assign": {
      "type": "object",
      "description": "Key is a string (e.g. \"1\"), and each item is an Analysis Control input object.",
      "minProperties": 1,
      "additionalProperties": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "ARCD": {
            "type": "boolean",
            "default": true,
            "description": "Auto Rotational DOF Constraint / Auto Normal Rotation Constraint"
          },
          "ANRC": {
            "type": "boolean",
            "default": true,
            "description": "Auto Rotational DOF Constraint / Auto Normal Rotation Constraint"
          },
          "CSECF": {
            "type": "boolean",
            "default": false,
            "description": "Consider Section Stiffness Scale Factor"
          },
          "CRBAR": {
            "type": "boolean",
            "default": false,
            "description": "Consider Reinforcement for Section Stiffness"
          },
          "TRS": {
            "type": "boolean",
            "default": true,
            "description": "Transfer Reactions to Master Node"
          },
          "CLATS": {
            "type": "boolean",
            "default": false,
            "description": "Change Local Axis of Tapered Section"
          },
          "BMSTRESS": {
            "type": "boolean",
            "default": false,
            "description": "Calculate Equivalent Beam Stresses"
          },
          "CLFORM": {
            "type": "boolean",
            "default": false,
            "description": "Classical Formula for Solid Element"
          },
          "BSCHG": {
            "type": "string",
            "enum": [
              "CONSTANT",
              "CHANGE"
            ],
            "default": "CHANGE",
            "description": "Beam Section Property Changes"
          },
          "CABINIT": {
            "type": "boolean",
            "default": true,
            "description": "Consider Initial Tension for Cable Element"
          },
          "TCELEM": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "NUMINC": {
                "type": "integer",
                "minimum": 1,
                "default": 1,
                "description": "Number of Increments"
              },
              "INTOUT": {
                "type": "string",
                "enum": [
                  "EVERY",
                  "LAST"
                ],
                "default": "LAST",
                "description": "Intermediate Output Request"
              },
              "CONVERGENCE": {
                "type": "object",
                "additionalProperties": false,
                "properties": {
                  "DISPL": {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "OPT_USE"
                    ],
                    "properties": {
                      "OPT_USE": {
                        "type": "boolean",
                        "description": "Displacement (U) / Load (P) / Work (W)"
                      },
                      "VALUE": {
                        "type": "number",
                        "description": "Displacement (U) / Load (P) / Work (W)"
                      }
                    },
                    "allOf": [
                      {
                        "description": "If OPT_USE = true, VALUE is required.",
                        "if": {
                          "properties": {
                            "OPT_USE": {
                              "const": true
                            }
                          },
                          "required": [
                            "OPT_USE"
                          ]
                        },
                        "then": {
                          "required": [
                            "VALUE"
                          ]
                        }
                      },
                      {
                        "description": "If OPT_USE = false, VALUE is not allowed.",
                        "if": {
                          "properties": {
                            "OPT_USE": {
                              "const": false
                            }
                          },
                          "required": [
                            "OPT_USE"
                          ]
                        },
                        "then": {
                          "not": {
                            "required": [
                              "VALUE"
                            ]
                          }
                        }
                      }
                    ],
                    "description": "Displacement (U) / Load (P) / Work (W)"
                  },
                  "LOAD": {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "OPT_USE"
                    ],
                    "properties": {
                      "OPT_USE": {
                        "type": "boolean",
                        "description": "Displacement (U) / Load (P) / Work (W)"
                      },
                      "VALUE": {
                        "type": "number",
                        "description": "Displacement (U) / Load (P) / Work (W)"
                      }
                    },
                    "allOf": [
                      {
                        "description": "If OPT_USE = true, VALUE is required.",
                        "if": {
                          "properties": {
                            "OPT_USE": {
                              "const": true
                            }
                          },
                          "required": [
                            "OPT_USE"
                          ]
                        },
                        "then": {
                          "required": [
                            "VALUE"
                          ]
                        }
                      },
                      {
                        "description": "If OPT_USE = false, VALUE is not allowed.",
                        "if": {
                          "properties": {
                            "OPT_USE": {
                              "const": false
                            }
                          },
                          "required": [
                            "OPT_USE"
                          ]
                        },
                        "then": {
                          "not": {
                            "required": [
                              "VALUE"
                            ]
                          }
                        }
                      }
                    ],
                    "description": "Displacement (U) / Load (P) / Work (W)"
                  },
                  "WORK": {
                    "type": "object",
                    "additionalProperties": false,
                    "required": [
                      "OPT_USE"
                    ],
                    "properties": {
                      "OPT_USE": {
                        "type": "boolean",
                        "description": "Displacement (U) / Load (P) / Work (W)"
                      },
                      "VALUE": {
                        "type": "number",
                        "description": "Displacement (U) / Load (P) / Work (W)"
                      }
                    },
                    "allOf": [
                      {
                        "description": "If OPT_USE = true, VALUE is required.",
                        "if": {
                          "properties": {
                            "OPT_USE": {
                              "const": true
                            }
                          },
                          "required": [
                            "OPT_USE"
                          ]
                        },
                        "then": {
                          "required": [
                            "VALUE"
                          ]
                        }
                      },
                      {
                        "description": "If OPT_USE = false, VALUE is not allowed.",
                        "if": {
                          "properties": {
                            "OPT_USE": {
                              "const": false
                            }
                          },
                          "required": [
                            "OPT_USE"
                          ]
                        },
                        "then": {
                          "not": {
                            "required": [
                              "VALUE"
                            ]
                          }
                        }
                      }
                    ],
                    "description": "Displacement (U) / Load (P) / Work (W)"
                  }
                },
                "anyOf": [
                  {
                    "properties": {
                      "DISPL": {
                        "properties": {
                          "OPT_USE": {
                            "const": true
                          }
                        },
                        "required": [
                          "OPT_USE"
                        ]
                      }
                    },
                    "required": [
                      "DISPL"
                    ]
                  },
                  {
                    "properties": {
                      "LOAD": {
                        "properties": {
                          "OPT_USE": {
                            "const": true
                          }
                        },
                        "required": [
                          "OPT_USE"
                        ]
                      }
                    },
                    "required": [
                      "LOAD"
                    ]
                  },
                  {
                    "properties": {
                      "WORK": {
                        "properties": {
                          "OPT_USE": {
                            "const": true
                          }
                        },
                        "required": [
                          "OPT_USE"
                        ]
                      }
                    },
                    "required": [
                      "WORK"
                    ]
                  }
                ],
                "description": "Displacement (U) / Load (P) / Work (W)"
              }
            },
            "description": "Tension/Compression Truss Element (서브다이얼로그 진입 — API 는 TCELEM 블록 직접 전송)"
          }
        }
      }
    }
  }
}

{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "Assign"
  ],
  "properties": {
    "Assign": {
      "type": "object",
      "description": "인덱스 문자열 키(예: \"1\")를 쓰는 맵. 각 항목은 DTO_BCGA_M1(Assign Boundary Combination) 입력",
      "minProperties": 1,
      "additionalProperties": {
        "type": "object",
        "unevaluatedProperties": false,
        "required": [
          "BC_ASSIGN",
          "BC_SELECT"
        ],
        "properties": {
          "BC_ASSIGN": {
            "type": "array",
            "description": "Assign Boundary Combination to Analyses & Load Cases (그리드의 각 행이 BC_ASSIGN 엔트리. UI 는 {Type, LoadCaseKey, BcctCombIndex} 로, DTO 는 {ANAL_TYPE, LCNAME, BGCNAME} 로 표현 (이름 기반))",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "ANAL_TYPE"
              ],
              "properties": {
                "ANAL_TYPE": {
                  "type": "string",
                  "description": "ANAL_TYPE (필수. enum ST/MV/SM/EIGV/RS/LTH/NLTH/PO 중 하나)",
                  "enum": [
                    "ST",
                    "MV",
                    "SM",
                    "EIGV",
                    "RS",
                    "LTH",
                    "NLTH",
                    "PO"
                  ]
                },
                "LCNAME": {
                  "type": "string",
                  "description": "LCNAME (ANAL_TYPE ∈ {ST, NLTH, PO} 시 필수. 나머지 해석 타입은 LCNAME 불필요 (단일 집합 해석). 지정 시 실제 Load Case 이름이어야 함)"
                },
                "BGCNAME": {
                  "type": "string",
                  "default": "",
                  "description": "BGCNAME (선택. 빈 문자열 = 변경 없음(-1). 지정 시 실제 BCCD 이름이어야 함)"
                }
              },
              "allOf": [
                {
                  "description": "ANAL_TYPE이 ST, NLTH, PO이면 LCNAME이 필수입니다.",
                  "if": {
                    "properties": {
                      "ANAL_TYPE": {
                        "enum": [
                          "ST",
                          "NLTH",
                          "PO"
                        ]
                      }
                    },
                    "required": [
                      "ANAL_TYPE"
                    ]
                  },
                  "then": {
                    "required": [
                      "LCNAME"
                    ]
                  }
                }
              ]
            }
          },
          "BC_SELECT": {
            "type": "array",
            "description": "Apply to Boundary Change (Apply 목록의 항목들이 BC_SELECT 배열로 직접 전송됨)",
            "items": {
              "type": "string",
              "enum": [
                "SECF",
                "ESSF",
                "EWSF",
                "PSSF",
                "WSSF",
                "CONS",
                "NSPR",
                "GSPR",
                "SSPS",
                "ELNK",
                "RIGD",
                "NLNK",
                "CGLP",
                "FRLS",
                "OFFS",
                "PRLS",
                "MCON"
              ]
            }
          }
        }
      }
    }
  }
}

