                  "description": "PERIOD_METHOD=1 (Approximate Period) then PERIOD_APPR_X and PERIOD_APPR_Y are required.",
                  "if": {
                    "properties": {
                      "PERIOD_METHOD": {
                        "const": 1
                      }
                    },
                    "required": [
                      "PERIOD_METHOD"
                    ]
                  },
                  "then": {
                    "required": [
                      "PERIOD_APPR_X",
                      "PERIOD_APPR_Y"
                    ]
                  }
                }
              ]
            },
            "ADDITIONAL_LOAD": {
              "type": "object",
              "additionalProperties": false,
