{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "Assign"
  ],
  "properties": {
    "Assign": {
      "type": "object",
      "description": "Key is a string (e.g. \"1\"), and each item is a Structure Type input object.",
      "minProperties": 1,
      "additionalProperties": {
        "type": "object",
        "unevaluatedProperties": false,
        "allOf": [
          {
            "type": "object",
            "properties": {
              "STYPE": {
                "type": "string",
                "enum": [
                  "_3D",
                  "XZ",
                  "YZ",
                  "XY",
                  "RZ"
                ],
                "default": "_3D",
                "description": "3-D / X-Z Plane / Y-Z Plane / X-Y Plane / Constraint RZ (UI 5 radio buttons are merged into one DTO enum field)"
              }
            }
          },
          {
            "type": "object",
            "required": [
              "MASS_CONTROL"
            ],
            "properties": {
              "MASS_CONTROL": {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "MASS_TYPE",
                  "SELFWEIGHT"
                ],
                "properties": {
                  "MASS_TYPE": {
                    "type": "string",
                    "enum": [
                      "LUMPED",
                      "CONSISTENT"
                    ],
                    "description": "Lumped Mass / Consistent Mass (2 radio buttons are merged into one enum field)"
                  },
                  "MASS_POS": {
                    "type": "string",
                    "enum": [
                      "CENTROID",
                      "OFFSET"
                    ],
                    "description": "Consider Mass at the Centroid of Section / Consider Mass at the Offset Position"
                  },
                  "SELFWEIGHT": {
                    "type": "boolean",
                    "description": "Convert Self-weight into Masses (true then MASS_AXIS is required)"
                  },
                  "MASS_AXIS": {
                    "type": "string",
                    "enum": [
                      "XYZ",
                      "XY",
                      "Z"
                    ],
                    "description": "Convert to X, Y, Z / Convert to X, Y / Convert to Z"
                  }
                },
                "allOf": [
                  {
                    "description": "If MASS_TYPE = LUMPED, MASS_POS is required.",
                    "if": {
                      "properties": {
                        "MASS_TYPE": {
                          "const": "LUMPED"
                        }
                      },
                      "required": [
                        "MASS_TYPE"
                      ]
                    },
                    "then": {
                      "required": [
                        "MASS_POS"
                      ]
                    }
                  },
                  {
                    "description": "If MASS_TYPE = CONSISTENT, MASS_POS is not allowed.",
                    "if": {
                      "properties": {
                        "MASS_TYPE": {
                          "const": "CONSISTENT"
                        }
                      },
                      "required": [
                        "MASS_TYPE"
                      ]
                    },
                    "then": {
                      "not": {
                        "required": [
                          "MASS_POS"
                        ]
                      }
                    }
                  },
                  {
                    "description": "If SELFWEIGHT = true, MASS_AXIS is required.",
                    "if": {
                      "properties": {
                        "SELFWEIGHT": {
                          "const": true
                        }
                      },
                      "required": [
                        "SELFWEIGHT"
                      ]
                    },
                    "then": {
                      "required": [
                        "MASS_AXIS"
                      ]
                    }
                  },
                  {
                    "description": "If SELFWEIGHT = false, MASS_AXIS is not allowed.",
                    "if": {
                      "properties": {
                        "SELFWEIGHT": {
                          "const": false
                        }
                      },
                      "required": [
                        "SELFWEIGHT"
                      ]
                    },
                    "then": {
                      "not": {
                        "required": [
                          "MASS_AXIS"
                        ]
                      }
                    }
                  },
                  {
                    "description": "If MASS_TYPE = CONSISTENT and SELFWEIGHT = true, MASS_AXIS must be XYZ.",
                    "if": {
                      "properties": {
                        "MASS_TYPE": {
                          "const": "CONSISTENT"
                        },
                        "SELFWEIGHT": {
                          "const": true
                        }
                      },
                      "required": [
                        "MASS_TYPE",
                        "SELFWEIGHT"
                      ]
                    },
                    "then": {
                      "properties": {
                        "MASS_AXIS": {
                          "const": "XYZ"
                        }
                      }
                    }
                  }
                ],
                "description": "Mass Control Parameter"
              }
            }
          },
          {
            "type": "object",
            "properties": {
              "GRAV": {
                "type": "number",
                "exclusiveMinimum": 0,
                "description": "Gravity Acceleration"
              },
              "TEMP": {
                "type": "number",
                "default": 0,
                "description": "Initial Temperature"
              }
            }
          },
          {
            "type": "object",
            "properties": {
              "ALIGNBEAM": {
                "type": "boolean",
                "default": false,
                "description": "Align Top of Beam Section with Center Line (X-Y Plane) for Display"
              },
              "ALIGNSLAB": {
                "type": "boolean",
                "default": false,
                "description": "Align Top of Slab(Plate) Section with Center Line (X-Y Plane) for Display"
              }
            }
          }
        ]
      }
    }
  }
}

{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "Assign"
  ],
  "properties": {
    "Assign": {
      "type": "object",
      "description": "Keys are string indices; each value is a SWIND request item.",
      "minProperties": 1,
      "patternProperties": {
        "^[0-9]+$": {
          "type": "object",
          "additionalProperties": false,
          "description": "SWIND request item. DESC and ADDITIONAL_LOAD are optional; WIND_CODE, SCALE_FACTOR_X, SCALE_FACTOR_Y, and PARAMETERS are required.",
          "required": [
            "WIND_CODE",
            "SCALE_FACTOR_X",
            "SCALE_FACTOR_Y",
            "PARAMETERS"
          ],
          "properties": {
            "WIND_CODE": {
              "type": "string",
              "const": "KDS(41-12: 2022)",
              "description": "Wind load code. Currently only KDS(41-12: 2022) is supported by this schema.",
              "enum": [
                "KDS(41-12: 2022)"
              ]
            },
            "DESC": {
              "type": "string",
              "default": "",
              "description": "Optional description."
            },
            "SCALE_FACTOR_X": {
              "type": "number",
              "description": "Scale factor for X direction."
            },
            "SCALE_FACTOR_Y": {
              "type": "number",
              "description": "Scale factor for Y direction."
            },
            "PARAMETERS": {
              "type": "object",
              "additionalProperties": false,
              "description": "KDS(41-12: 2022) wind parameters. INPUT_METHOD selects method-specific fields.",
              "required": [
                "INPUT_METHOD"
              ],
              "properties": {
                "INPUT_METHOD": {
                  "type": "integer",
                  "enum": [
                    0,
                    1,
                    2
                  ],
                  "description": "Input method for KDS(41-12: 2022) wind parameters."
                },
                "EXP_CATEGORY": {
                  "type": "integer",
                  "description": "Exposure category.",
                  "enum": [
                    0,
                    1,
                    2,
                    3
                  ]
                },
                "WIND_SPEED": {
                  "type": "number",
                  "description": "Basic wind speed."
                },
                "IMPORTANCE_FACTOR": {
                  "type": "number",
                  "description": "Importance factor."
                },
                "ROOF_HEIGHT": {
                  "type": "number",
                  "description": "Roof height. If omitted, the product system value is used.",
                  "default": "system"
                },
                "CE": {
                  "type": "number",
                  "description": "Exposure coefficient. If omitted, default 1.0 is used.",
                  "default": 1
                },
                "TOPOGRAPHIC_EFFECT": {
                  "type": "object",
                  "additionalProperties": false,
                  "description": "Optional topographic effect. Omission means OPT_USE=false.",
                  "required": [
                    "OPT_USE"
                  ],
                  "properties": {
                    "OPT_USE": {
                      "type": "boolean",
                      "default": false,
                      "description": "Whether to use topographic effect."
                    },
                    "KZT": {
                      "type": "number",
                      "description": "Topographic factor."
                    }
                  },
                  "allOf": [
                    {
                      "description": "OPT_USE=true then KZT is required.",
                      "if": {
                        "properties": {
                          "OPT_USE": {
                            "const": true
                          }
                        },
                        "required": [
                          "OPT_USE"
                        ]
                      },
                      "then": {
                        "required": [
                          "KZT"
                        ]
                      }
                    },
                    {
                      "description": "OPT_USE=false then KZT must not be provided.",
                      "if": {
                        "properties": {
                          "OPT_USE": {
                            "const": false
                          }
                        },
                        "required": [
                          "OPT_USE"
                        ]
                      },
                      "then": {
                        "not": {
                          "required": [
                            "KZT"
                          ]
                        }
                      }
                    }
                  ]
                },
                "DIRECTION_FACTOR_X": {
                  "type": "number",
                  "description": "Direction factor for X direction."
                },
                "DIRECTION_FACTOR_Y": {
                  "type": "number",
                  "description": "Direction factor for Y direction."
                },
                "RIGIDITY": {
                  "type": "integer",
                  "description": "Rigidity classification."
                },
                "GUST_FACTOR_X": {
                  "type": "number",
                  "description": "Gust factor for X direction."
                },
                "GUST_FACTOR_Y": {
                  "type": "number",
                  "description": "Gust factor for Y direction."
                },
                "FORCE_COEF": {
                  "type": "object",
                  "additionalProperties": false,
                  "description": "Optional force coefficient. Omission means OPT_USE=false.",
                  "required": [
                    "OPT_USE"
                  ],
                  "properties": {
                    "OPT_USE": {
                      "type": "boolean",
                      "default": false,
                      "description": "Whether to use user-defined force coefficient."
                    },
                    "FORCE_COEF": {
                      "type": "number",
                      "description": "Force coefficient value."
                    }
                  },
