                      },

                      "required": [

                        "OPT_USE"

                      ]

                    },

                    "then": {

                      "required": [

                        "SUBSEQ_LOAD"

                      ]

                    }

                  },

                  {

                    "description": "SUBSEQ_LOAD = 0 -> LCTYPE, CASE required",

                    "if": {

                      "properties": {

                        "OPT_USE": {

                          "const": true

                        },

                        "SUBSEQ_LOAD": {

                          "const": 0

                        }

                      },

                      "required": [

                        "OPT_USE",

                        "SUBSEQ_LOAD"

                      ]

                    },

                    "then": {

                      "required": [

                        "LCTYPE",

                        "CASE"

                      ]

                    }

                  },

                  {

                    "description": "SUBSEQ_LOAD = 1 or 2 -> LCTYPE, CASE must not be provided",

                    "if": {

                      "properties": {

                        "OPT_USE": {

                          "const": true

                        },

                        "SUBSEQ_LOAD": {

                          "enum": [

                            1,

                            2

                          ]

                        }

                      },

                      "required": [

                        "OPT_USE",

                        "SUBSEQ_LOAD"

                      ]

                    },

                    "then": {

                      "not": {

                        "anyOf": [

                          {

                            "required": [

                              "LCTYPE"

                            ]

                          },

                          {

                            "required": [

                              "CASE"

                            ]

                          }

                        ]

                      }

                    }

                  }

                ]

